                MemorySegment out = arena.allocate(ValueLayout.JAVA_DOUBLE, Math.max(16L * n, 1));
                boolean ok = call(() -> (boolean) ISOCURVE_BEZIERS.invokeExact(h, d, t, out));
                if (!ok) throw failure("isocurve_beziers");
